    { id: "coupang", label: "쿠팡 검색", emoji: "🛒", url: "https://www.coupang.com/np/search?q={q}" },
    { id: "naver", label: "네이버 검색", emoji: "🟢", url: "https://search.shopping.naver.com/search/all?query={q}" }
