/* 이 블로그·페르소나가 건강 카테고리인가 */
BS.healthContext = function (blogId, personaId) {
  var H = BS.HEALTH_CLAIMS || {};
  var bid = String(blogId || "");
  var pid = String(personaId || "");
  if ((H.blogs || []).indexOf(bid) >= 0) return true;
  if ((H.personas || []).indexOf(pid) >= 0) return true;
  return false;
};

/* 결과물 검사기 — 글에서 걸린 금지 표현을 등장 순서대로 돌려준다 (중복 없이) */
BS.healthHits = function (text) {
  var H = BS.HEALTH_CLAIMS || {};
  var t = String(text == null ? "" : text);
  var out = [];
  (H.patterns || []).forEach(function (p) {
    var re;
    try { re = new RegExp(p, "g"); } catch (e) { return; }
    var m;
    while ((m = re.exec(t)) !== null) {
      var s = String(m[0] || "").replace(/\s+/g, " ").trim();
      if (s && out.indexOf(s) < 0) out.push(s);
      if (re.lastIndex === m.index) re.lastIndex++;
    }
  });
  return out;
};
