/* 플랫폼 id → 정보 (없으면 쿠팡파트너스) */
BS.platform = function (id) {
  var list = (BS.PRODUCT && BS.PRODUCT.platforms) || [];
  for (var i = 0; i < list.length; i++) if (list[i].id === id) return list[i];
  return list[0];
};
BS.disclosureFor = function (id) { return (BS.platform(id) || {}).disclosure || BS.DISCLOSURE; };
/* 링크 주소 → 제휴 플랫폼 자동 감지 (v2.2.1)
   화면에서는 수동 선택이 더 강하게 기억되고, 주소를 붙여넣으면 그 플랫폼으로 맞춰 준다. */
BS.platformFromUrl = function (url) {
  var u = String(url == null ? "" : url).toLowerCase();
  if (!u) return "";
  var list = (BS.PRODUCT && BS.PRODUCT.platforms) || [];
  for (var i = 0; i < list.length; i++) {
    var keys = list[i].detect || [];
    for (var j = 0; j < keys.length; j++) {
      if (u.indexOf(String(keys[j]).toLowerCase()) >= 0) return list[i].id;
    }
  }
  return "";
};
BS.modeInfo = function (id) {
  for (var i = 0; i < BS.MODES.length; i++) if (BS.MODES[i].id === id) return BS.MODES[i];
  return BS.MODES[0];
};

