  minAuditChars: 500,      // 2단계 결과가 공백 제외 이 글자수보다 짧으면 비정상 응답으로 본다
  minAuditRatio: 0.6,      // 2단계 결과가 1단계 초안의 이 비율보다 짧으면 잘린 응답으로 본다
