/* ---------- 형광펜 2색 + 굵게 강조 (v1.7.2 · 2026-11-17 지연님 요청) ----------
   지연님이 스마트에디터 사진 두 장을 보내며 "상황에 따라 이렇게 표시도 해 줄 수 있어?"라고
   요청했다. 화면에는 ① 핵심 결론·요점 문장이 노란 형광펜, ② 꼭 확인할 조건·주의사항 문장이
   연한 하늘색 형광펜, ③ 그 밖의 중요한 단어·숫자는 굵게 되어 있었다.
   AI는 원고 안에서 기호로만 표시하고, 앱이 미리보기와 스마트에디터 복사본에서 색으로 바꾼다.

     ==문장==   → 노란 형광펜(#fff3a3)  : 핵심 결론, 첫째·둘째·셋째 요점
     @@문장@@  → 하늘 형광펜(#d9f3f4) : 확인할 조건·주의사항·체크포인트
     **단어**   → 굵게                 : 형광펜 밖 본문 속 중요한 단어·숫자·기한

   하늘색 기호로 @@를 고른 이유: 이메일 주소(a@b.com)에는 홑@만 있어 @@와 겹치지 않고,
   ~~(취소선)·__(밑줄)·^^(웃음 표시)처럼 본문에 우연히 나올 일도 없어 오인식이 가장 적다. */
BS.HL = {
  yellow: { mark: "==문장==", token: "==", bg: "#fff3a3", name: "노란 형광펜" },
  blue: { mark: "@@문장@@", token: "@@", bg: "#d9f3f4", name: "하늘 형광펜" },
  bold: { mark: "**단어**", token: "**", name: "굵게" },
  budget: "노란색·하늘색을 합쳐 4~8문장(소제목당 1~2문장) · 굵게는 문단마다 1~2곳"
};

