  "굵게 " + BS.HL.bold.mark + " — 형광펜을 칠하지 않은 본문 문장 안에서 중요한 단어, 숫자·금액·기한, 핵심 구절에만 쓴다. 문단 전체를 굵게 하지 않는다.",
  "남발 금지 — 한 글 전체에서 노란색과 하늘색을 합쳐 4~8문장(소제목당 1~2문장)만 친다. 글 전체가 노랗고 파래지면 아무것도 강조되지 않는다.",
  "형광펜은 본문 문장에만 — 제목·소제목·목차·표 안·해시태그·출처·면책사항·작업 메모에는 쓰지 않는다.",
  "문법 고정 — 노랑은 ==문장==, 하늘은 @@문장@@ 두 가지뿐이다. __, ~~, ^^, [[...]] 같은 다른 기호를 섞지 않고, 문장 안에 =나 @@를 넣지 않는다.",
  "문장부호는 형광펜 안쪽 — '==방문 견적은 최소 3곳에서 받으세요.=='처럼 문장을 통째로 감싼다. 낱말 한두 개만 칠하지 않는다.",
  "한 문장에 두 색을 겹치지 않는다. 형광펜 안의 핵심 단어는 겹쳐서 굵게 해도 된다(예: ==**추가 비용**은 계약서에 적어야 해요.==)."
