/* 🏷️ 태그 1개 강제 (v2.3.4 · 2026-11-20)
   모델이 규칙을 어기고 '#태그1 #태그2 …'를 내놓아도, 화면·복사·업로드 요청에는
   첫 단어 하나만 남긴다. 발행 화면에서 45자 뭉치 태그가 되는 일을 막는 마지막 그물.
   (지연님이 직접 고친 값은 건드리지 않는다 — parse 단계에서만 쓴다) */
BS.threadTagOne = function (text) {
  var s = String(text == null ? "" : text)
    .replace(/\r?\n/g, " ")
    .replace(/#/g, " ")
    .replace(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}]/gu, " ");
  var words = s.replace(/[()\[\]{}"`\u201C\u201D\u2018\u2019]/g, " ")
    .split(/\s+/)
    .map(function (w) { return w.replace(/^[-*·,.;:!?\u2026]+/, "").replace(/[-*·,.;:!?\u2026]+$/, ""); })
    .filter(function (w) {
      if (!w) return false;
      if (/^(태그|해시태그|주제|없음|none)$/i.test(w)) return false;
      return true;
    });
  if (!words.length) return "";
  return words[0].slice(0, 30);
};

/* 블로그·주제로 스레드 페르소나 고르기 (없으면 1번) */
BS.threadPersona = function (blogId, topic) {
  var list = (BS.THREADS && BS.THREADS.personas) || [];
  var t = String(topic || "");
  var i;
  for (i = 0; i < list.length; i++) {
    if (list[i].match && list[i].match.some(function (k) { return t.indexOf(k) >= 0; }) &&
        (list[i].blog === blogId || list[i].no === 5)) return list[i];
  }
  for (i = 0; i < list.length; i++) if (list[i].blog === blogId && !list[i].match) return list[i];
  return list[0];
};

