/* 페르소나 id → 페르소나 (없으면 null) */
BS.persona = function (id) {
  var list = (BS.PERSONAS && BS.PERSONAS.list) || [];
  var key = String(id || "");
  for (var i = 0; i < list.length; i++) if (list[i].id === key) return list[i];
  return null;
};

/* 블로그 id → 기본 추천 페르소나 id (매핑에 없으면 fallback) */
BS.personaDefault = function (blogId) {
  var P = BS.PERSONAS || {};
  var id = (P.blogDefault || {})[String(blogId || "")] || P.fallback || "living_fact";
  return BS.persona(id) ? id : (P.fallback || "living_fact");
};

/* 블로그 id + 직접 고른 id → 실제 쓸 페르소나 id (고른 값이 유효하면 그대로) */
BS.personaForBlog = function (blogId, pickedId) {
  return BS.persona(pickedId) ? pickedId : BS.personaDefault(blogId);
};

