/* 원고 블로그 → 업로드 계정 기본값 (모르는 블로그는 첫 계정)
   v2.0.0 — 구글 블로거 카드는 네이버·스레드 3계정과 무관하다. null을 돌려주고
   화면은 '이 카드는 스레드 업로드 계정이 없습니다 — 복사해서 직접 올리세요'라고 안내한다. */
BS.threadAccountFor = function (blogId) {
  var B = BS.blogById(blogId);
  if (B && B.kind === "blogger") return null;
  var list = (BS.THREAD_UPLOAD && BS.THREAD_UPLOAD.accounts) || [];
  var i, j, blogs;
  for (i = 0; i < list.length; i++) {
    blogs = list[i].blogs || [];
    for (j = 0; j < blogs.length; j++) if (blogs[j] === blogId) return list[i];
  }
  return list[0] || null;
};

/* 블로그 id → 카드 (없으면 null) — v2.0.0 */
BS.blogById = function (id) {
  var list = BS.BLOGS || [];
  for (var i = 0; i < list.length; i++) if (list[i].id === id) return list[i];
  return null;
};

/* 구글 블로거 카드인가 — v2.0.0 */
BS.isBlogger = function (blog) {
  var b = blog && blog.id ? blog : BS.blogById(blog);
  return !!(b && b.kind === "blogger");
};

/* 계정 id → 계정 (없으면 null) */
BS.threadAccountById = function (id) {
  var list = (BS.THREAD_UPLOAD && BS.THREAD_UPLOAD.accounts) || [];
  var i;
  for (i = 0; i < list.length; i++) if (list[i].id === id) return list[i];
  return null;
};

