/* 모델이 구글 실시간 검색을 붙일 수 있는지 — Flash Lite 계열은 미지원 */
BS.webSearchSupported = function (model) {
  var m = String(model == null ? "" : model).toLowerCase().trim();
  if (!m) return false;
  var cfg = BS.WEB_SEARCH || {};
  if ((cfg.unsupported || []).indexOf(m) >= 0) return false;
  if (/lite/.test(m)) return false;   // Flash Lite 계열은 google_search 미지원
  return true;
};

