/* 키워드 하나 → { id, label, short, desc, hit, basis }
   hit = 실제로 걸린 단어(툴팁에 근거로 보여 준다), 없으면 기본값 정보글 */
BS.kwIntent = function (text) {
  var s = String(text == null ? "" : text).toLowerCase();
  var R = BS.KW_INTENT, M = R.meta;
  function pack(id, hit) {
    return {
      id: id, label: M[id].label, short: M[id].short, desc: M[id].desc, hit: hit || "",
      basis: hit ? "‘" + hit + "’ 단어 때문에 " + M[id].label
        : "규칙에 걸리는 단어가 없어 기본값 " + M[id].label
    };
  }
  function hit(list) {
    for (var i = 0; i < list.length; i++) {
      if (s.indexOf(String(list[i]).toLowerCase()) >= 0) return list[i];
    }
    return "";
  }
  var h = hit(R.rules.issue);
  /* " vs " 는 스포츠 대진(newcastle vs arsenal)에도, 제품 비교(갤럭시 vs 아이폰)에도 쓰인다.
     상품 단어가 함께 있으면 구매·비교글로 두고, 아니면 이슈로 본다. */
  if (h && (h !== " vs " || !hit(R.rules.buy))) return pack("issue", h);
  h = hit(R.rules.infoStrong);
  if (h) return pack("info", h);
  h = hit(R.rules.buy);
  if (h) return pack("buy", h);
  h = hit(R.rules.infoWeak);
  if (h) return pack("info", h);
  return pack("info", "");
};
